async function acceptEscalation(jobId,role){
 if(S.busy)return toast("CENTRAL IS ALREADY PROCESSING AN ACTION","bad");
 const parent=S.jobs.find(x=>x.id===jobId); if(!parent)return toast("ESCALATION SOURCE NOT FOUND","bad");
 if(!role)return toast("ESCALATION SPECIALIST NOT FOUND","bad");
 const existing=S.jobs.some(x=>x.parent_id===jobId&&x.to_role===role&&["QUEUED","RECEIVED","WORKING","HANDOFF","WAITING","PROPOSED","APPROVAL_REQUIRED"].includes(x.state));
 if(existing)return toast("THAT ESCALATION IS ALREADY ACTIVE","bad");
 S.busy=true;
 try{
  const D=window.ESCIE_AGENT_DISPATCHER, P=window.ESCIE_AGENT_PROTOCOL, session=ses(), createdBy=session?.user?.id, conversationId=parent.conversation_id||uid();
  const label=D?.workerSummary?.(role)||"Review the request from the existing specialist result.";
  const payload={text:String(parent.payload?.text||""),source:"CENTRAL_ESCALATION",routing:"operator-accepted-escalation",parent_result_id:jobId,escalated_from_role:parent.from_role||parent.to_role||"SPECIALIST",escalated_to_role:role,summary:label,execution_mode:role===P?.roles?.FUNDING?"RESEARCH_AND_DRAFT":"SPECIALIST_WORK",requires_human_approval:true,human_gate:"required_before_submission_or_external_effect"};
  await A.enqueueAgentJob({conversation_id:conversationId,parent_id:jobId,from_role:"central-orchestrator",to_role:role,message_type:"HANDOFF",state:"QUEUED",priority:parent.priority||"normal",route_id:parent.route_id||"escalation",route_mode:"ADAPTIVE_ESCALATION",route_reason:"Operator accepted specialist escalation from a specialist result.",escalation_source_id:jobId,escalation_decision:"ACCEPTED",payload,created_by:createdBy});
  S.busy=false;toast("ESCALATION ACCEPTED — "+(D?.workerSummary?"SPECIALIST ADDED":"WORK QUEUED"));load();
 }catch(e){S.busy=false;toast("ESCALATION FAILED — "+String(e?.message||e),"bad")}
}
function declineEscalation(jobId,role){
 const parent=S.jobs.find(x=>x.id===jobId);if(!parent)return;
 const next={...(parent.payload||{}),escalation_decisions:{...((parent.payload||{}).escalation_decisions||{}),[role]:{decision:"DECLINED",at:new Date().toISOString(),actor:"HUMAN_OPERATOR"}}};
 A.request("/agent_jobs?id=eq."+encodeURIComponent(jobId)+"&workspace_id=eq."+encodeURIComponent(wid()),ses(),{method:"PATCH",headers:{Prefer:"return=representation"},body:JSON.stringify({payload:next,escalation_decision:"DECLINED",escalation_source_id:jobId})}).then(()=>{toast("ESCALATION DECLINED");load()}).catch(e=>toast("ESCALATION DECISION FAILED — "+String(e?.message||e),"bad"));
}

function synthesisCard(results){const items=results||[];if(!items.length)return '<div class="desk-empty">NO CENTRAL SYNTHESIS YET.</div>';const groups=new Map();items.forEach(j=>{const k=String(j.conversation_id||j.id);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(j)});return [...groups.entries()].map(([conversationId,rows])=>{const first=rows[0]||{},route=first.route_id||first.payload?.route_id||"auto",mode=first.route_mode||first.payload?.route_mode||"AUTO",request=String(first.payload?.text||first.payload?.instruction||first.payload?.summary||"Central request").slice(0,220),signals=[...new Set(rows.flatMap(j=>Array.isArray(j.payload?.analysis?.signals)?j.payload.analysis.signals:[]))],lanes=[...new Set(rows.flatMap(j=>Array.isArray(j.payload?.analysis?.next_lanes)?j.payload.analysis.next_lanes:[]))],attention=[...new Set(rows.flatMap(j=>Array.isArray(j.payload?.analysis?.attention)?j.payload.analysis.attention:[]))],human=rows.some(j=>j.state==="APPROVAL_REQUIRED"||j.payload?.requires_human_approval!==false);return '<article class="desk-synthesis"><div class="desk-synthesis-head"><div><div class="kicker">CENTRAL SYNTHESIS</div><h3>'+esc(request)+'</h3></div><span class="pill '+(human?"warn":"")+'">'+(human?"HUMAN DECISION REQUIRED":"ANALYSIS")+'</span></div><div class="desk-synthesis-grid"><div><strong>ROUTE</strong><p>'+esc(route)+" · "+esc(mode)+'</p></div><div><strong>SPECIALISTS</strong><p>'+rows.length+" result"+(rows.length===1?"":"s")+'</p></div><div><strong>RISK / ATTENTION</strong><p>'+esc(signals.concat(attention).join(" · ")||"No elevated risk signal detected.")+'</p></div><div><strong>SUGGESTED NEXT LANES</strong><p>'+esc(lanes.join(" · ")||"No additional lane suggested.")+'</p></div></div><div class="desk-synthesis-note">Central consolidates findings here. Suggestions do not silently change route, canon, publication, or external state.</div><div class="desk-actions"><button class="btn small" data-continue-conversation="'+esc(conversationId)+'">CONTINUE THREAD</button></div></article>'}).join("")}function consolidationCard(results){const groups=new Map();(results||[]).forEach(j=>{const id=String(j.conversation_id||j.id);if(!groups.has(id))groups.set(id,[]);groups.get(id).push(j)});if(!groups.size)return '<div class="desk-empty">NO SPECIALIST FINDINGS.</div>';return [...groups.entries()].map(([id,items])=>{const first=items[0],route=first.route_id||first.payload?.route_id||"auto";const title=String(first.payload?.text||first.payload?.summary||"Central request").slice(0,180);const analysis=items.reduce((a,j)=>{const x=j.payload?.analysis||{};a.signals.push(...(Array.isArray(x.signals)?x.signals:[]));a.next.push(...(Array.isArray(x.next_lanes)?x.next_lanes:[]));if(x.attention&&!a.attention)a.attention=x.attention;return a},{signals:[],next:[],attention:""});const uniq=a=>[...new Set(a.filter(Boolean).map(String))];const signals=uniq(analysis.signals),next=uniq(analysis.next);const findings=items.map(j=>'<div class="desk-consolidated-item"><b>'+esc(j.from_role||"SPECIALIST")+'</b><p>'+esc(String(j.payload?.summary||j.payload?.text||"No finding returned.").slice(0,600))+'</p></div>').join("");const signalHtml=signals.length?'<div class="desk-synthesis-block"><strong>RISK / ATTENTION</strong><div class="desk-chip-row">'+signals.slice(0,10).map(x=>'<span class="pill warn">'+esc(x)+'</span>').join("")+'</div></div>':'<div class="desk-synthesis-block"><strong>RISK / ATTENTION</strong><p class="desk-muted">No elevated risk signal returned by the specialists.</p></div>';const nextHtml=next.length?'<div class="desk-synthesis-block"><strong>SUGGESTED NEXT LANES</strong><div class="desk-chip-row">'+next.slice(0,8).map(x=>'<span class="pill">'+esc(x)+'</span>').join("")+'</div></div>':'';return '<article class="desk-item desk-consolidation"><div class="desk-title">CENTRAL CONSOLIDATION</div><div class="desk-meta">'+esc(route)+' · '+items.length+' SPECIALIST RESULTS</div><p>'+esc(title)+'</p><div class="desk-synthesis-head"><div><strong>SYNTHESIS READY</strong><span>Central has gathered the current specialist findings.</span></div><span class="pill warn">HUMAN DECISION REQUIRED</span></div><div class="desk-synthesis-summary">'+esc(String(items.map(j=>j.payload?.summary||j.payload?.text||"").filter(Boolean).join(" · ")||"No consolidated summary returned.").slice(0,1200))+'</div>'+signalHtml+nextHtml+'<div class="desk-consolidated-list">'+findings+'</div><div class="desk-actions"><button class="btn small" data-continue-conversation="'+esc(id)+'">CONTINUE THREAD</button></div></article>'}).join("")}
function resultCard(j){
 const s=j.state||"PROPOSED";
 const chain=S.jobs.filter(x=>x.conversation_id&&x.conversation_id===j.conversation_id).sort((a,b)=>String(a.created_at||"").localeCompare(String(b.created_at||"")));
 const first=chain[0]||j;
 const q=first.payload?.text||first.payload?.instruction||first.message_type||"Conversation";
 const detail=chain.map((x,i)=>'<div class="thread-event"><b>'+esc(String(i+1).padStart(2,"0"))+' · '+esc(x.message_type||"EVENT")+'</b><span>'+esc(x.state||"")+'</span><p>'+esc(String(x.payload?.text||x.payload?.summary||x.payload?.instruction||"").slice(0,500))+'</p>'+((x.payload?.operator_feedback||x.payload?.human_review?.latest?.feedback)?'<div class="thread-feedback"><strong>OPERATOR FEEDBACK</strong><br>'+esc(String(x.payload?.operator_feedback||x.payload?.human_review?.latest?.feedback))+'</div>':'')+'</div>').join("");
 const tid=esc(String(j.conversation_id||j.id));
 const candidates=Array.isArray(j.payload?.escalation_candidates)?j.payload.escalation_candidates:[];
 const decisions=j.payload?.escalation_decisions||{};
 const activeChildren=S.jobs.filter(x=>x.parent_id===j.id);
 const escalationHtml=candidates.filter(role=>!decisions[role]&&!activeChildren.some(x=>x.to_role===role)).length?'<div class="desk-escalation"><div class="desk-escalation-head"><strong>ADAPTIVE ESCALATION</strong><span>Central detected a possible next specialist.</span></div>'+candidates.filter(role=>!decisions[role]&&!activeChildren.some(x=>x.to_role===role)).map(role=>'<div class="desk-escalation-row"><div><b>'+esc(role)+'</b><p>'+esc(window.ESCIE_AGENT_DISPATCHER?.workerSummary?.(role)||"Review this lane before adding it.")+'</p></div><div class="desk-actions"><button class="btn small primary" type="button" data-escalate="'+esc(j.id)+'" data-escalate-role="'+esc(role)+'">ADD SPECIALIST</button><button class="btn small" type="button" data-decline-escalation="'+esc(j.id)+'" data-escalate-role="'+esc(role)+'">DECLINE</button></div></div>').join("")+'</div>':'';
 return '<article class="desk-item thread-card"><div class="thread-head"><div><div class="desk-title">'+esc(String(q).slice(0,180))+'</div><div class="desk-meta">THREAD · '+esc(String(j.conversation_id||j.id))+' · '+esc(String(chain.length||1))+' EVENTS</div></div><button class="btn small" type="button" data-thread-toggle="'+tid+'">OPEN THREAD</button></div><div class="thread-preview"><div class="desk-meta">'+esc(j.from_role||"SPECIALIST")+' → '+esc(j.to_role||"CENTRAL")+' · '+esc(s)+'</div><p>'+esc(String(j.payload?.text||j.payload?.summary||"Specialist result").slice(0,260))+'</p></div><div class="thread-detail hidden" id="thread-'+tid+'">'+detail+escalationHtml+'<div class="desk-actions"><button class="btn small primary" data-j="'+esc(j.id)+'" data-jd="APPROVE">APPROVE</button><button class="btn small" data-j="'+esc(j.id)+'" data-jd="REJECT">REJECT</button><button class="btn small" data-j="'+esc(j.id)+'" data-jd="QUARANTINE">QUARANTINE</button><button class="btn small" data-j="'+esc(j.id)+'" data-jd="MODIFY">MODIFY</button></div></div></article>';
}

function card(r){const s=r.approval?.state||"PENDING",detailId="record-"+String(r.id).replace(/[^a-zA-Z0-9_-]/g,"_"),media=Array.isArray(r.media)?r.media:[],history=Array.isArray(r.audit_history)?r.audit_history:[],tags=Array.isArray(r.tags)?r.tags:[];return '<article class="desk-item record-card"><label class="record-select"><input type="checkbox" data-record-select value="'+esc(r.id)+'"></label><div><div class="desk-title">'+esc(r.title)+'</div><div class="desk-meta">'+esc(r.type||"FRAGMENT")+' · '+esc(r.status||"DRAFT")+' · '+esc(s)+'</div><p>'+esc((r.description||"").slice(0,220))+'</p><div class="desk-record-meta"><span>'+media.length+' ASSET'+(media.length===1?"":"S")+'</span><span>'+history.length+' HISTORY EVENT'+(history.length===1?"":"S")+'</span>'+(tags.length?'<span>'+esc(tags.slice(0,4).join(" · "))+"</span>":"")+'</div></div><div class="desk-actions"><button class="btn small" data-record-toggle="'+esc(detailId)+'">OPEN RECORD</button><button class="btn small" data-record-edit="'+esc(r.id)+'">EDIT</button>'+([ "PENDING","UNREVIEWED"].includes(s)?'<button class="btn small primary" data-a="'+esc(r.id)+'" data-d="ACCEPT">ACCEPT</button><button class="btn small" data-a="'+esc(r.id)+'" data-d="DECLINE">DECLINE</button><button class="btn small" data-a="'+esc(r.id)+'" data-d="QUARANTINE">QUARANTINE</button>':"")+'</div></article><div class="record-detail hidden" id="'+esc(detailId)+'"><div class="record-detail-grid"><div><strong>DESCRIPTION</strong><p>'+esc(r.description||"No description.")+'</p><strong>PROJECT</strong><p>'+esc(r.project||"—")+'</p><strong>VISIBILITY</strong><p>'+esc(r.visibility||"—")+' · PUBLICATION '+esc(r.publication_state||"NOT_REQUESTED")+'</p></div><div><strong>ASSETS</strong><p>'+esc(media.map(m=>m.original_name||m.mime_type||"asset").join(" · ")||"No assets attached.")+'</p><strong>LAST UPDATE</strong><p>'+esc(r.updated_at||"—")+'</p><strong>REVIEW</strong><p>'+esc(r.approval?.operator_feedback||"No operator feedback.")+'</p></div></div><div class="record-history">'+(history.slice(-8).reverse().map(h=>'<div><b>'+esc(h.action||"EVENT")+'</b><span>'+esc(h.at||"")+'.</span><p>'+esc(h.reason||h.note||"")+"</p></div>").join("")||"<div>No history yet.</div>")+"</div></div>"}function ask(kind,title,desc,list){return '<div class="desk-panel desk-ask"><div class="kicker">CENTRAL OPERATOR</div><h2>'+title+'</h2><p>'+desc+'</p><label>CONVERSATION<select id="deskConversation"><option value="">NEW CONVERSATION</option></select></label><div id="deskConversationSummary"></div><textarea id="deskRequest" rows="7" placeholder="What do you need?"></textarea><div id="deskRouteSuggestions" class="desk-route-suggestions"></div><div class="desk-formgrid"><label>ROUTE<select id="deskRole"><option value="central-orchestrator">CENTRAL</option><option value="archive-evidence">ARCHIVE / EVIDENCE</option><option value="brain-relationships">RELATIONSHIPS</option><option value="creative-work">CREATIVE</option><option value="release-distribution">DISTRIBUTION</option><option value="audit-guardian">GUARDIAN</option><option value="legal-contract">LEGAL / CONTRACTS</option><option value="rights-clearance">RIGHTS / CLEARANCE</option><option value="grants-funding">GRANTS / FUNDING</option><option value="editor-proofreading">EDITOR / PROOFREADING</option><option value="ip-business-admin">IP / BUSINESS ADMIN</option></select></label><label>PRIORITY<select id="deskPriority"><option>normal</option><option>high</option><option>urgent</option><option>low</option></select></label><label>SERVICE<select id="deskService"><option value="AUTO">AUTO — CENTRAL CHOOSES</option><option value="RESEARCH">RESEARCH</option><option value="IMAGE">IMAGE / ART</option><option value="DISTRIBUTION">DISTRIBUTION</option><option value="GAME">GAME PLATFORM</option><option value="AUTOMATION">AUTOMATION</option><option value="LEGAL">LEGAL / CONTRACTS</option><option value="RIGHTS">RIGHTS / CLEARANCE</option><option value="FUNDING">GRANTS / FUNDING</option><option value="EDITOR">EDITOR / PROOFREADING</option><option value="ADMIN">IP / BUSINESS ADMIN</option></select></label></div><button id="'+(kind==="QUESTION"?"deskAskBtn":"deskTaskBtn")+'" class="btn primary">'+title+'</button></div><div class="sectionTitle"><div><div class="kicker">IN FLIGHT</div><h2>RECENT</h2></div></div><div class="desk-list">'+(list.slice(0,30).map(j=>'<article class="desk-item"><div><div class="desk-title">'+esc(j.payload?.text||j.message_type)+'</div><div class="desk-meta">'+esc(j.state||"QUEUED")+' · '+esc(j.to_role||"CENTRAL")+'</div></div><span class="pill">'+esc(j.priority||"normal")+'</span></article>').join("")||'<div class="desk-empty">NOTHING YET.</div>')+'</div>'}function renderRouteSuggestions(){const box=$("deskRouteSuggestions"),input=$("deskRequest"),D=window.ESCIE_AGENT_DISPATCHER;if(!box||!input||!D?.suggestRoutes)return;const t=input.value.trim();if(!t){box.innerHTML="<div class=\"desk-route-empty\">CENTRAL WILL SUGGEST THE BEST ROUTE AFTER YOU DESCRIBE THE JOB.</div>";return}const requested=$("deskRole")?.value||"central-orchestrator",routes=D.suggestRoutes(t,requested==="central-orchestrator"?null:requested)||[];if(!routes.length){box.innerHTML="";return}if(!routes.some(r=>r.id===S.routeChoice))S.routeChoice=routes[0].id;box.innerHTML="<div class=\"desk-route-head\"><span>ROUTE OPTIONS</span><small>Central can change the path before work begins.</small></div>"+routes.map((r,i)=>"<button type=\"button\" class=\"desk-route "+(r.id===S.routeChoice?"selected":"")+" \" data-route-choice=\""+esc(r.id)+"\"><span><b>"+esc(r.label)+(r.recommended?" · RECOMMENDED":"")+"</b><small>"+esc(r.why)+"</small><em>"+esc((r.roles||[]).map(x=>D.workerSummary?.(x)?x:x).join(" → ")||"CENTRAL")+"</em></span></button>").join("");box.querySelectorAll("[data-route-choice]").forEach(b=>b.onclick=()=>{S.routeChoice=b.dataset.routeChoice;renderRouteSuggestions()})}function continueConversation(id){S.tab="ASK CENTRAL";S.continueConversation=String(id||"");render();const sel=$("deskConversation");if(sel&&S.continueConversation&&[...sel.options].some(o=>o.value===S.continueConversation)){sel.value=S.continueConversation;const box=$("deskConversationSummary");if(box)box.innerHTML=conversationSummary(S.continueConversation)}}
